static void finish(u32 value) { *(volatile u32 *)0x100000 = value; for (;;) {} }
static void run_batch_group(u32 group)
{
 u32 i;
 struct test_request *r = &batch_req[group];
 if (npu_crypto_test_request_group(group, r, 76 + r->aad_len + r->length) != 1)
  finish(0x13333);
 for (i = 0; i < 16; i++) if (r->tag[i] != tags[8][i]) finish(0x13333);
 r->op = 1;
 if (npu_crypto_test_request_group(group, r, 76 + r->aad_len + r->length) != 1)
  finish(0x13333);
 for (i = 0; i < r->length; i++)
  if (r->data[r->aad_len+i] != (u8)i) finish(0x13333);
 batch_done[group] = 1;
}

void qemu_hart_entry(u32 hart)
{
 u32 group = hart / AIROHA_CRYPTO_NPU_HARTS_PER_PACKET;

 if (hart < 6 && group && group < AIROHA_CRYPTO_NPU_BATCH_SIZE &&
     !(hart % AIROHA_CRYPTO_NPU_HARTS_PER_PACKET)) {
  while (!batch_go) {}
  run_batch_group(group);
  for (;;) __asm__ volatile("wfi");
 }
 crypto_worker(hart);
}

void test_main(void)
{
 u32 i, j, count, group;
 __asm__ volatile("fence rw,rw" ::: "memory");
 npu_crypto_qemu_go = 1;
 for (count = 0; !npu_crypto_qemu_ready(); count++)
  if (count == 200000000) finish(0x13333);
 for (group = 0; group < AIROHA_CRYPTO_NPU_BATCH_SIZE; group++) {
 req.version = 2;
 for (j = 0; j < sizeof(lengths)/sizeof(lengths[0]); j++) {
  req.length = lengths[j]; req.aad_len = aad_lengths[j]; req.op = 0;
  for (i = 0; i < 12; i++) req.nonce[i] = i+j*29;
  for (i = 0; i < 32; i++) req.key[i] = i+j*17;
  for (i = 0; i < req.aad_len; i++) req.data[i] = 255-i;
  for (i = 0; i < req.length; i++) req.data[req.aad_len+i] = i;
  if (npu_crypto_test_request_group(group, &req, 76 + req.aad_len + req.length) != 1) finish(0x13333);
  for (i = 0; i < 16; i++) if (req.tag[i] != tags[j][i]) finish(0x13333);
  req.op = 1;
  req.tag[0] ^= 1;
  if (npu_crypto_test_request_group(group, &req, 76 + req.aad_len + req.length) != 2) finish(0x13333);
  req.tag[0] ^= 1;
  if (npu_crypto_test_request_group(group, &req, 76 + req.aad_len + req.length) != 1) finish(0x13333);
  for (i = 0; i < req.length; i++) if (req.data[req.aad_len+i] != (u8)i) finish(0x13333);
 }
 }
 for (j = 0; j < 4; j++) {
  for (i = 0; i < 32; i++) keybuf[j+i] = i;
  for (i = 0; i < 12; i++) noncebuf[j+i] = i;
  for (i = 0; i < 320; i++) { input[j+i] = i; output[j+i] = 0xa5; }
  npu_chacha20_xor_range(output+j, input+j, 320, keybuf+j, noncebuf+j, 1, 5);
  for (i = 0; i < 64; i++) if (output[j+i] != 0xa5) finish(0x13333);
  for (i = 64; i < 320; i++) if (output[j+i] != ciphertext[i]) finish(0x13333);
  npu_chacha20_xor_range(input+j, input+j, 320, keybuf+j, noncebuf+j, 1, 5);
  for (i = 0; i < 64; i++) if (input[j+i] != (u8)i) finish(0x13333);
  for (i = 64; i < 320; i++) if (input[j+i] != ciphertext[i]) finish(0x13333);
 }
 for (group = 0; group < AIROHA_CRYPTO_NPU_BATCH_SIZE; group++) {
  struct test_request *r = &batch_req[group];
  r->version = 2; r->length = lengths[8]; r->aad_len = aad_lengths[8]; r->op = 0;
  for (i = 0; i < 12; i++) r->nonce[i] = i + 8 * 29;
  for (i = 0; i < 32; i++) r->key[i] = i + 8 * 17;
  for (i = 0; i < r->aad_len; i++) r->data[i] = 255 - i;
  for (i = 0; i < r->length; i++) r->data[r->aad_len+i] = i;
 }
 __asm__ volatile("fence rw,rw" ::: "memory");
 batch_go = 1;
 run_batch_group(0);
 for (group = 1; group < AIROHA_CRYPTO_NPU_BATCH_SIZE; group++) {
  for (count = 0; !batch_done[group]; count++)
   if (count == 200000000) finish(0x13333);
 }
 finish(0x5555);
}
